using FluentValidation;
namespace FintechApp.Requests.ReferralRegistration { public class UpdateReferralRegistrationRequest { public int ReferralRegistrationID { get; set; } public int UserID { get; set; } public string MobileNumber { get; set; } = string.Empty; public string ReferralCode { get; set; } = string.Empty; public int CreatedByUserID { get; set; } public bool IsBenefitUtilize { get; set; } public decimal ReferralAmount { get; set; } } public class UpdateReferralRegistrationRequestValidator : AbstractValidator<UpdateReferralRegistrationRequest> { public UpdateReferralRegistrationRequestValidator() { RuleFor(x => x.ReferralRegistrationID).GreaterThan(0); } } }
